    solution:
      "from datetime import datetime, timedelta\n\ndef _field(text, lo, hi):\n    values = set()\n    for term in text.split(','):\n        base, _, step = term.partition('/')\n        if base == '*':\n            start, end = lo, hi\n        elif '-' in base:\n            a, b = base.split('-')\n            start, end = int(a), int(b)\n        else:\n            start = end = int(base)\n        values.update(range(start, end + 1, int(step) if step else 1))\n    return sorted(values)\n\ndef next_runs(spec: str, after: str, count: int) -> list:\n    minute_text, hour_text, weekday_text = spec.split()\n    minutes = _field(minute_text, 0, 59)\n    hours = _field(hour_text, 0, 23)\n    weekdays = set(_field(weekday_text, 0, 6))\n    after_dt = datetime.strptime(after, '%Y-%m-%d %H:%M')\n    day = after_dt.replace(hour=0, minute=0)\n    out = []\n    while len(out) < count:\n        if day.weekday() in weekdays:\n            for h in hours:\n                for m in minutes:\n                    run = day.replace(hour=h, minute=m)\n                    if run > after_dt and len(out) < count:\n                        out.append(run.strftime('%Y-%m-%d %H:%M'))\n        day += timedelta(days=1)\n    return out\n",
