    solution:
      "def sessionize(events: list, gap: int) -> list:\n    by_user = {}\n    for user, ts in events:\n        by_user.setdefault(user, []).append(ts)\n    sessions = []\n    for user, stamps in by_user.items():\n        stamps.sort()\n        current = None\n        for ts in stamps:\n            if current is not None and ts - current['end'] <= gap:\n                current['end'] = ts\n                current['events'] += 1\n            else:\n                current = {'user': user, 'start': ts, 'end': ts, 'events': 1}\n                sessions.append(current)\n    sessions.sort(key=lambda s: (s['start'], s['user']))\n    return sessions\n",
