    solution:
      "import re\n\ndef expand_vars(config: dict) -> dict:\n    done = {}\n    active = set()\n\n    class Problem(Exception):\n        pass\n\n    def expand(name):\n        if name in done:\n            return done[name]\n        if name in active:\n            raise Problem({'error': 'cycle'})\n        active.add(name)\n\n        def swap(match):\n            ref, fallback = match.group(1), match.group(2)\n            if ref in config:\n                return expand(ref)\n            if fallback is not None:\n                return fallback\n            raise Problem({'error': 'undefined', 'name': ref})\n\n        done[name] = re.sub(r'\\$\\{([A-Za-z0-9_]+)(?::-([^}]*))?\\}', swap, config[name])\n        active.discard(name)\n        return done[name]\n\n    try:\n        for name in sorted(config):\n            expand(name)\n    except Problem as problem:\n        return problem.args[0]\n    return {'values': done}\n",
