    solution:
      "def split_args(line: str):\n    args = []\n    current = []\n    started = False\n    quote = None\n    i = 0\n    while i < len(line):\n        ch = line[i]\n        if quote == \"'\":\n            if ch == \"'\":\n                quote = None\n            else:\n                current.append(ch)\n        elif quote == '\"':\n            if ch == '\"':\n                quote = None\n            elif ch == '\\\\' and i + 1 < len(line) and line[i + 1] in '\"\\\\':\n                current.append(line[i + 1])\n                i += 1\n            else:\n                current.append(ch)\n        elif ch == \"'\" or ch == '\"':\n            quote = ch\n            started = True\n        elif ch == '\\\\':\n            if i + 1 == len(line):\n                return None\n            current.append(line[i + 1])\n            started = True\n            i += 1\n        elif ch == ' ':\n            if started:\n                args.append(''.join(current))\n                current = []\n                started = False\n        else:\n            current.append(ch)\n            started = True\n        i += 1\n    if quote:\n        return None\n    if started:\n        args.append(''.join(current))\n    return args\n",
