    solution:
      "STAGES = ['created', 'picked_up', 'in_transit', 'out_for_delivery', 'delivered']\n\ndef track_parcel(scans: list) -> dict:\n    rank = -1\n    history = []\n    ignored = 0\n    for ts, status in sorted(scans, key=lambda scan: scan[0]):\n        if status in STAGES and STAGES.index(status) > rank:\n            rank = STAGES.index(status)\n            history.append([ts, status])\n        else:\n            ignored += 1\n    return {'status': STAGES[rank] if rank >= 0 else None, 'history': history, 'ignored': ignored}\n",
